import java.util.ArrayList;
import java.util.List;

public class ConstructionOrderLogTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            List<String> defaulted = ConstructionOrderLog.trace(null);
            check("default trace",
                    "[Component(ctor), Child.describe label=null, ConstructionOrderLog(ctor,default)]",
                    String.valueOf(defaulted));
            check("default trace has three entries", 3, defaulted.size());

            List<String> named = ConstructionOrderLog.trace("alpha");
            check("named trace",
                    "[Component(ctor), Child.describe label=null, ConstructionOrderLog(ctor,alpha)]",
                    String.valueOf(named));
            check("the base constructor logs first", "Component(ctor)", named.get(0));
            check("the override runs before the field is assigned",
                    "Child.describe label=null", named.get(1));
            check("the subclass body logs last",
                    "ConstructionOrderLog(ctor,alpha)", named.get(2));

            List<String> shared = new ArrayList<>();
            ConstructionOrderLog built = new ConstructionOrderLog(shared, "beta");
            check("constructing directly writes to the caller's log",
                    "[Component(ctor), Child.describe label=null, ConstructionOrderLog(ctor,beta)]",
                    String.valueOf(shared));

            built.describe();
            check("calling describe afterwards sees the real label",
                    "Child.describe label=beta", shared.get(3));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

