import java.util.ArrayList;
import java.util.List;

/**
 * Provided -- do not edit.
 *
 * Every step this base constructor takes is written into the shared log, so the
 * order in which things really happen becomes visible.
 */
class Component {

    protected final List<String> log;

    Component(List<String> log) {
        this.log = log;
        log.add("Component(ctor)");
        describe();
    }

    protected void describe() {
        log.add("Component.describe");
    }
}

public class ConstructionOrderLog extends Component {

    private String label;

    public ConstructionOrderLog(List<String> log) {
        this(log, "default");
    }

    public ConstructionOrderLog(List<String> log, String label) {
        super(log);
        this.label = label;
        log.add("ConstructionOrderLog(ctor," + label + ")");
    }

    @Override
    protected void describe() {
        log.add("Child.describe label=" + label);
    }

    public static List<String> trace(String label) {
        List<String> log = new ArrayList<>();
        if (label == null) {
            new ConstructionOrderLog(log);
        } else {
            new ConstructionOrderLog(log, label);
        }
        return log;
    }
}
